-- 77 The Heist: each room's camera tracks the thief, its view confined
-- to the room's outline (`confine` on the camera). The camera of the room
-- the thief is in gets the highest `priority` and so the screen; it blends
-- the view across from the last one over its `blend` seconds. C clears
-- every confine (the view looks past the walls at the garden), B makes
-- every hand-over a cut. Generated by tools/gen_scenes.py.

script = { tick_rate = 60 }

local nav = require("nav")
local SCENE = "scenes/77-the-heist.scene"
local BLEND = 0.9
local ROOMS = {
    { cam = "CamHall", label = "ENTRANCE HALL", poly = { { 0, 0 }, { 1800, 0 }, { 1800, 1200 }, { 0, 1200 } } },
    { cam = "CamGallery", label = "LONG GALLERY", poly = { { 1800, 100 }, { 4400, 100 }, { 4400, 2600 }, { 2900, 2600 }, { 2900, 1100 }, { 1800, 1100 } } },
    { cam = "CamRotunda", label = "ROTUNDA", poly = { { 4500.0, 3802.1 }, { 4002.1, 4300.0 }, { 3297.9, 4300.0 }, { 2800.0, 3802.1 }, { 2800.0, 3097.9 }, { 3297.9, 2600.0 }, { 4002.1, 2600.0 }, { 4500.0, 3097.9 } } },
    { cam = "CamVault", label = "VAULT", poly = { { 1700, 3000 }, { 2800, 3000 }, { 2800, 3900 }, { 1700, 3900 } } }
}
local captions = true
local confined = true
local blending = true
local held = false
local current = 0
local t = 0
local thief, cam_label, room_label, rec_dot, clock, status

local function inside(poly, x, y)
    local hit = false
    local j = #poly
    for i = 1, #poly do
        local a, b = poly[i], poly[j]
        if (a[2] > y) ~= (b[2] > y) and x < (b[1] - a[1]) * (y - a[2]) / (b[2] - a[2]) + a[1] then
            hit = not hit
        end
        j = i
    end
    return hit
end

local function show_status()
    UI.set_text(status, "confine " .. (confined and "on" or "off") .. "   blend "
        .. (blending and (BLEND .. " s") or "cut") .. (held and "   thief held" or ""))
end

function init(entity)
    thief = Entity.find_by_name("Thief")
    cam_label = Entity.find_by_name("CamLabel")
    room_label = Entity.find_by_name("RoomLabel")
    rec_dot = Entity.find_by_name("RecDot")
    clock = Entity.find_by_name("Clock")
    status = Entity.find_by_name("Status")
    for _, room in ipairs(ROOMS) do room.e = Entity.find_by_name(room.cam) end
    show_status()
end

function update(entity, dt)
    nav.tick(SCENE)
    t = t + dt
    if Input.is_key_just_pressed("Tab") then captions = nav.toggle_ui_captions(captions) end
    if Input.is_key_just_pressed("C") then
        confined = not confined
        for _, room in ipairs(ROOMS) do Camera.set(room.e, "confine", confined and room.poly or {}) end
        show_status()
    end
    if Input.is_key_just_pressed("B") then
        blending = not blending
        for _, room in ipairs(ROOMS) do Camera.set(room.e, "blend", blending and BLEND or 0) end
        show_status()
    end
    if Input.is_key_just_pressed("Space") then
        held = not held
        PathFollow.set(thief, "playing", not held)
        show_status()
    end
    -- Hand the screen to the camera of the room the thief is in.
    local x, y = Transform.get_position(thief)
    for i, room in ipairs(ROOMS) do
        if i ~= current and inside(room.poly, x, y) then
            if current > 0 then Camera.set(ROOMS[current].e, "priority", 0) end
            Camera.set(room.e, "priority", 10)
            current = i
            UI.set_text(cam_label, string.format("CAM %02d", i))
            UI.set_text(room_label, room.label)
            break
        end
    end
    UI.set_visible(rec_dot, math.floor(t * 1.5) % 2 == 0)
    local s = math.floor(t) + 3 * 3600 + 12 * 60
    UI.set_text(clock, string.format("04 OCT 2026   %02d:%02d:%02d", math.floor(s / 3600) % 24,
        math.floor(s / 60) % 60, s % 60))
end
